(function(){function init(){var cards=document.querySelectorAll('.person-card');for(var i=0;i<cards.length;i++){(function(card){var bio=card.querySelector('.person-card__bio');if(!bio)return;var t=card.querySelector('.person-card__bio-toggle');if(!t){t=document.createElement('span');t.className='person-card__bio-toggle';t.setAttribute('role','button');t.textContent='Show more';t.style.cssText='display:inline-flex;align-self:flex-start;color:rgba(33,31,28,0.7);font-size:0.9375rem;font-weight:500;text-decoration:underline;cursor:pointer;margin:0 0 1rem;padding:0;background:transparent;border:0;font-family:Geist,system-ui,sans-serif;transition:color 200ms';bio.insertAdjacentElement('afterend',t);}if(bio.scrollHeight<=bio.clientHeight+2){t.style.display='none';return;}var open=false;t.onclick=function(e){e.preventDefault();open=!open;bio.style.maxHeight=open?'none':'';bio.style.overflow=open?'visible':'';t.textContent=open?'Show less':'Show more';};})(cards[i]);}}if(document.readyState==='complete'){init();}else{window.addEventListener('load',init);}})();